/**
 * Countries as FastApply names them, with their phone calling codes.
 *
 * Copied from FastApply's web app (src/lib/constants/countries.ts, PHONE_COUNTRY_CODES) on
 * 2026-10-10 so Scout stores the same country names and the same phone-code ids FastApply
 * stores for its own users: `phoneCountryCode` is the ISO id ("US", "CA"), never "+1", which
 * cannot tell the United States from Canada. "Czech Republic" is stored as "Czechia" because
 * FastApply's API folds it to that. Generated by scripts/build-country-table.mjs from that file; rerun it
 * rather than editing by hand.
 */
export interface CountryRow { id: string; dial: string; name: string }

